---
import BaseLayout from "../../layouts/BaseLayout.astro"
import { listAuthorsEntries } from "../../lib/contentcatalog"

export async function getStaticPaths() {
  const entries = await listAuthorsEntries()
  return entries.map(entry => ({ params: { slug: entry.id }, props: { entry } }))
}

const { entry } = Astro.props
---
<BaseLayout title={`${entry.data.name} — Field Notes`} description={entry.data.bio ?? entry.data.name}>
  <h1>{entry.data.name}</h1>
</BaseLayout>

const posts = byId(await getCollection("posts"))
  const authorIds = new Set((await getCollection("authors")).map(author => author.id))
  for (const post of posts) {
    if (!authorIds.has(post.data.author)) throw new Error((post.filePath ?? "src/content/posts/" + post.id) + ': field author "' + post.data.author + '" is not the id of an entry in src/content/authors/')
  }
  return posts
